71:/**
72: * Extract text from a PDF buffer using OCR (Tesseract).
73: *
74: * Each page is rendered to a 2× PNG (for accuracy), then fed to Tesseract.
75: * Pages are processed sequentially to limit peak memory.
76: *
77: * @returns Extracted text, empty string if no pages or OCR yields nothing.
78: */
79:export async function ocrPdf(pdfBuffer: Buffer): Promise<string> {
80:  // Render all pages to PNG buffers.
81:  // pdf-to-png-converter expects ArrayBuffer, not Node Buffer directly.
82:  const pages = await pdfToPng(pdfBuffer.buffer as ArrayBuffer, {
83:    disableFontFace: true,
84:    useSystemFonts: false,
85:    viewportScale: 2.0, // higher resolution → better OCR accuracy
86:  });
87:
88:  if (pages.length === 0) return "";
89:
90:  const worker = await getWorker();
91:  const pageTexts: string[] = [];
92:
93:  for (const page of pages) {
94:    // page.content is a PNG Buffer; skip if undefined (malformed page)
95:    if (!page.content) continue;
96:    const { data } = await worker.recognize(page.content);
97:    const trimmed = data.text.trim();
98:    if (trimmed.length > 0) {
99:      pageTexts.push(trimmed);
100:    }
101:  }
102:
103:  return pageTexts.join("\n\n");
104:}
