1:/**
2: * Heuristic chapter detection for plain text content.
3: * Covers B-17: Tự động chia theo heading (Heuristic)
4: *
5: * Detects chapter boundaries using multiple patterns:
6: * 1. Keyword regex: chapter/chương/phần/part + number
7: * 2. Numbered headings: "1. Title"
8: * 3. Markdown H1: "# Title"
9: * 4. ALL CAPS short lines (< 60 chars)
10: * 5. Fallback: single chapter with all content
11: */
12:
13:export interface DetectedChapter {
14:  title: string;
15:  content: string;
16:  chapterNumber: number;
17:  wordCount: number;
18:  /** true if wordCount < 200 */
19:  short: boolean;
20:}
21:
22:/** Minimum word count before a chapter is flagged as "short" */
23:const SHORT_CHAPTER_THRESHOLD = 200;
24:
25:// ── Pattern matchers ────────────────────────────────────────────────────────
26:
27:/** Chapter/Chương/Phần/Part followed by a number */
28:const KEYWORD_HEADING_RE =
29:  /^(chapter|chương|phần|part)\s+\d+/i;
30:
31:/** Numbered heading: "1. Title", "1.1 Title", "1) Title" (digit(s) with optional sub-numbers) */
32:const NUMBERED_HEADING_RE = /^\d+(?:\.\d+)*[.)]\s+\S/;
33:
34:/** Markdown H1 only (not H2+) */
35:const MARKDOWN_H1_RE = /^# (.+)$/;
36:
37:/** ALL CAPS line shorter than 60 characters (trimmed) */
38:function isAllCapsHeading(line: string): boolean {
39:  const trimmed = line.trim();
40:  if (trimmed.length === 0 || trimmed.length > 60) return false;
41:  // Must have at least one letter and all letters must be uppercase
42:  const hasLetter = /[A-Z]/.test(trimmed);
43:  if (!hasLetter) return false;
44:  // No lowercase letters allowed
45:  return !/[a-z]/.test(trimmed);
46:}
47:
48:// ── Heading detection ───────────────────────────────────────────────────────
49:
50:interface HeadingMatch {
51:  lineIndex: number;
52:  title: string;
53:}
54:
55:/**
56: * Scan all lines and return heading positions + extracted titles.
57: * Priority: keyword > numbered > markdown H1 > ALL CAPS
58: * We use the FIRST pattern family that yields ≥ 2 headings.
59: * If none yield ≥ 2 we combine everything found.
60: */
61:function findHeadings(lines: string[]): HeadingMatch[] {
62:  const keyword: HeadingMatch[] = [];
63:  const numbered: HeadingMatch[] = [];
64:  const markdownH1: HeadingMatch[] = [];
65:  const allCaps: HeadingMatch[] = [];
66:
67:  for (let i = 0; i < lines.length; i++) {
68:    const line = lines[i].trim();
69:    if (line.length === 0) continue;
70:
71:    // Keyword pattern: "Chapter 1 Introduction" → title = full line
72:    if (KEYWORD_HEADING_RE.test(line)) {
73:      keyword.push({ lineIndex: i, title: line });
74:      continue; // keyword takes precedence, don't double-count
75:    }
76:
77:    // Markdown H1
78:    const h1Match = MARKDOWN_H1_RE.exec(line);
79:    if (h1Match) {
80:      markdownH1.push({ lineIndex: i, title: h1Match[1] });
81:      continue;
82:    }
83:
84:    // Numbered heading
85:    if (NUMBERED_HEADING_RE.test(line)) {
86:      // title = everything after "N. "
87:      const title = line.replace(/^\d+\.\s+/, "");
88:      numbered.push({ lineIndex: i, title });
89:      continue;
90:    }
91:
92:    // ALL CAPS
93:    if (isAllCapsHeading(line)) {
94:      allCaps.push({ lineIndex: i, title: line });
95:    }
96:  }
97:
98:  // Return the first family that has ≥ 2 headings
99:  if (keyword.length >= 2) return keyword;
100:  if (markdownH1.length >= 2) return markdownH1;
101:  if (numbered.length >= 2) return numbered;
102:  if (allCaps.length >= 2) return allCaps;
103:
104:  // Combine all found (may be 0 or 1)
105:  const combined = [...keyword, ...markdownH1, ...numbered, ...allCaps];
106:  combined.sort((a, b) => a.lineIndex - b.lineIndex);
107:  return combined;
108:}
109:
110:// ── Word counting ───────────────────────────────────────────────────────────
111:
112:function countWords(text: string): number {
113:  const trimmed = text.trim();
114:  if (trimmed.length === 0) return 0;
115:  return trimmed.split(/\s+/).length;
116:}
117:
118:// ── Public API ──────────────────────────────────────────────────────────────
119:
120:/**
121: * Detect chapters in plain text using heuristic heading patterns.
122: *
123: * Returns an array of `DetectedChapter` objects with sequential numbering.
124: * If no headings are found, returns a single chapter containing all text.
125: */
126:export function detectChapters(text: string): DetectedChapter[] {
127:  const lines = text.split("\n");
128:  const headings = findHeadings(lines);
129:
130:  // ── Fallback: no headings found ─────────────────────────────────────────
131:  if (headings.length === 0) {
132:    const wc = countWords(text);
133:    return [
134:      {
135:        title: "Untitled",
136:        content: text,
137:        chapterNumber: 1,
138:        wordCount: wc,
139:        short: wc < SHORT_CHAPTER_THRESHOLD,
140:      },
141:    ];
142:  }
143:
144:  // ── Build chapters from heading boundaries ──────────────────────────────
145:  const chapters: DetectedChapter[] = [];
146:
147:  // If there's text before the first heading, include it as a preamble chapter
148:  if (headings[0].lineIndex > 0) {
149:    const preambleLines = lines.slice(0, headings[0].lineIndex);
150:    const preambleContent = preambleLines.join("\n").trim();
151:    if (preambleContent.length > 0) {
152:      const wc = countWords(preambleContent);
153:      chapters.push({
154:        title: "Preamble",
155:        content: preambleContent,
156:        chapterNumber: 1,
157:        wordCount: wc,
158:        short: wc < SHORT_CHAPTER_THRESHOLD,
159:      });
160:    }
161:  }
162:
163:  for (let h = 0; h < headings.length; h++) {
164:    const heading = headings[h];
165:    const startLine = heading.lineIndex + 1; // content starts after heading line
166:    const endLine =
167:      h + 1 < headings.length ? headings[h + 1].lineIndex : lines.length;
168:
169:    const contentLines = lines.slice(startLine, endLine);
170:    const content = contentLines.join("\n").trim();
171:    const wc = countWords(content);
172:
173:    chapters.push({
174:      title: heading.title,
175:      content,
176:      chapterNumber: chapters.length + 1,
177:      wordCount: wc,
178:      short: wc < SHORT_CHAPTER_THRESHOLD,
179:    });
180:  }
181:
182:  return chapters;
183:}
